320	impl ReleaseDecisionV1 {
321	    pub const SCHEMA_VERSION: u8 = 1;
322	
323	    /// Creates a canonical decision or rejects an ambiguous release roster.
324	    pub fn new(mut entries: Vec<ReleaseDecisionEntry>) -> Result<Self, ReleaseDecisionError> {
325	        if entries.is_empty() {
326	            return Err(ReleaseDecisionError::EmptyRoster);
327	        }
328	        for entry in &mut entries {
329	            entry.reasons.sort();
330	            entry.reasons.dedup();
331	            if entry.reasons.is_empty() {
332	                return Err(ReleaseDecisionError::MissingReason {
333	                    package: entry.package.clone(),
334	                });
335	            }
336	        }
337	        entries.sort_by(|left, right| left.package.cmp(&right.package));
338	        if entries.windows(2).any(|pair| pair[0].package == pair[1].package) {
339	            return Err(ReleaseDecisionError::DuplicatePackage);
340	        }
341	        let digest = decision_digest(&entries);
342	        Ok(Self {
343	            schema_version: Self::SCHEMA_VERSION,
344	            entries,
345	            digest,
346	        })
347	    }
348	}
349	
350	fn decision_digest(entries: &[ReleaseDecisionEntry]) -> DecisionDigest {
351	    let mut transcript = CanonicalTranscript::decision_v1();
352	    for entry in entries {
353	        transcript.push_str("package", &entry.package.to_string());
354	        transcript.push_str("target-version", entry.target_version.render());
355	        for reason in &entry.reasons {
356	            transcript.push_str(
357	                "reason",
358	                &serde_json::to_string(reason).expect("closed reason serializes"),
359	            );
360	        }
361	    }
362	    DecisionDigest::from_transcript(&transcript)
363	}
