1	//! Deterministic, graph-owned release roster decisions.
2	//!
3	//! This is deliberately separate from `PublishPlan`: it records the exact
4	//! package/version authority that later intent construction consumes, without
5	//! exposing a mutation route.
6	
7	use callisto_model::{
8	    BumpReason, CommandRunner, CommitSha, Ecosystem, ReleaseDecisionEntry, ReleaseDecisionV1, ReleaseInclusionReason,
9	    ReleasePackageId, Version,
10	};
11	
12	use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};
13	
14	/// Derives the durable roster from a freshly computed version plan.
15	///
16	/// The caller supplies the plan from the same workspace observation; this
17	/// function never inspects `PublishPlan` or a caller-provided release roster.
18	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
19	    workspace: &Workspace<'_, R, D>,
20	    plan: &VersionPlan,
21	) -> Result<ReleaseDecisionV1, GraphError> {
22	    let mut package_ids = std::collections::BTreeMap::new();
23	    for package in workspace.graph.packages() {
24	        let ids = package
25	            .canonical_manifests()
26	            .map(|manifest| ReleasePackageId::new(manifest.ecosystem(), package.id.name()))
27	            .collect::<Result<Vec<_>, _>>()
28	            .map_err(|_error| GraphError::ReleaseIntentStale)?;
29	        package_ids.insert(package.id.clone(), ids);
30	    }
31	
32	    let mut entries = Vec::new();
33	    for bump in &plan.bumps {
34	        let ids = package_ids.get(&bump.package).ok_or(GraphError::ReleaseIntentStale)?;
35	        for id in ids {
36	            entries.push(ReleaseDecisionEntry {
37	                package: id.clone(),
38	                target_version: bump.to.clone(),
39	                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
40	            });
41	        }
42	    }
43	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale)
44	}
45	
46	/// Derives a durable decision for explicit, exact release identities.
47	///
48	/// A linked group is one release unit: selecting any member includes every
49	/// member of that linked group which the version plan selected. All other
50	/// packages remain outside the authority boundary. The caller must pass
51	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
52	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
53	/// for release authority.
54	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
55	    workspace: &Workspace<'_, R, D>,
56	    plan: &VersionPlan,
57	    selections: &[ReleasePackageId],
58	) -> Result<ReleaseDecisionV1, GraphError> {
59	    let complete = derive_release_decision(workspace, plan)?;
60	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
61	    if selected.len() != selections.len() {
62	        return Err(GraphError::ReleaseIntentStale);
63	    }
64	    if selected
65	        .iter()
66	        .any(|selection| !complete.entries.iter().any(|entry| &entry.package == *selection))
67	    {
68	        return Err(GraphError::ReleaseIntentStale);
69	    }
70	
71	    let linked_groups = complete
72	        .entries
73	        .iter()
74	        .filter(|entry| selected.contains(&entry.package))
75	        .flat_map(|entry| entry.reasons.iter())
76	        .filter_map(|reason| match reason {
77	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
78	            _ => None,
79	        })
80	        .collect::<std::collections::BTreeSet<_>>();
81	
82	    let entries = complete
83	        .entries
84	        .into_iter()
85	        .filter(|entry| {
86	            selected.contains(&entry.package)
87	                || entry.reasons.iter().any(|reason| {
88	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if linked_groups.contains(group_id))
89	                })
90	        })
91	        .collect();
92	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale)
93	}
94	
95	/// Derives the release roster from a merged release commit already checked out
96	/// at `release_commit`.
97	///
98	/// This is intentionally *not* a second call to [`crate::commands::plan_version`].
99	/// The release PR has already used its pending changesets to calculate and
100	/// apply the version plan.  At merge time those changesets are gone, and the
101	/// immutable merge commit is the authority.  We therefore require that it
102	/// deletes its consumed changesets, and the canonical manifest versions and
103	/// configured changelogs form exactly the resulting roster.
104	///
105	/// The caller must check out the exact merge commit in detached HEAD state
106	/// before creating an intent.  GitHub-specific PR/approval provenance belongs
107	/// in the workflow boundary; this graph function verifies the local,
108	/// provider-neutral commit delta only.
109	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
110	    workspace: &Workspace<'_, R, D>,
111	    release_commit: &CommitSha,
112	) -> Result<ReleaseDecisionV1, GraphError> {
113	    let head = git_stdout(workspace.runner, &workspace.root, &["rev-parse", "HEAD"])?;
114	    let head = CommitSha::parse(&head).map_err(|_error| GraphError::ReleaseIntentStale)?;
115	    if &head != release_commit {
116	        return Err(GraphError::ReleaseIntentStale);
117	    }
118	
119	    let parent_ref = format!("{}^", release_commit.as_str());
120	    let parent = git_stdout(workspace.runner, &workspace.root, &["rev-parse", &parent_ref])?;
121	    CommitSha::parse(&parent).map_err(|_error| GraphError::ReleaseIntentStale)?;
122	
123	    let changed = git_stdout(
124	        workspace.runner,
125	        &workspace.root,
126	        &[
127	            "diff-tree",
128	            "--no-commit-id",
129	            "--name-status",
130	            "-r",
131	            "--no-renames",
132	            &parent,
133	            release_commit.as_str(),
134	        ],
135	    )?;
136	    let changed = parse_name_status(&changed)?;
137	    let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
138	    let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
139	    let deleted_changesets = changed
140	        .iter()
141	        .filter_map(|(status, path)| {
142	            (status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md")).then_some(path)
143	        })
144	        .collect::<Vec<_>>();
145	    if deleted_changesets.is_empty() {
146	        return Err(GraphError::ReleaseIntentStale);
147	    }
148	
149	    let mut selected = std::collections::BTreeSet::new();
150	    for path in deleted_changesets {
151	        let source = git_file(workspace.runner, &workspace.root, &parent, path)?;
152	        let changeset = callisto_format::parse_changeset(&source).map_err(|_error| GraphError::ReleaseIntentStale)?;
153	        for entry in changeset.entries {
154	            selected.extend(resolve_changeset_entry(workspace, &entry.name)?);
155	        }
156	    }
157	
158	    let changed_paths = changed
159	        .iter()
160	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
161	        .collect::<std::collections::BTreeSet<_>>();
162	    let mut entries = Vec::new();
163	    let mut observed = std::collections::BTreeSet::new();
164	    for package in workspace.graph.packages() {
165	        let package_ids = package
166	            .canonical_manifests()
167	            .map(|manifest| {
168	                ReleasePackageId::new(manifest.ecosystem(), package.id.name())
169	                    .map_err(|_error| GraphError::ReleaseIntentStale)
170	            })
171	            .collect::<Result<Vec<_>, _>>()?;
172	        let package_is_selected = package_ids.iter().any(|id| selected.contains(id));
173	        if package_is_selected {
174	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleaseIntentStale)?;
175	            if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
176	                return Err(GraphError::ReleaseIntentStale);
177	            }
178	        }
179	        for manifest in package.canonical_manifests() {
180	            let id = ReleasePackageId::new(manifest.ecosystem(), package.id.name())
181	                .map_err(|_error| GraphError::ReleaseIntentStale)?;
182	            let path = manifest.path.to_string_lossy();
183	            let before = manifest_version_at(workspace.runner, &workspace.root, &parent, &path, manifest.ecosystem())?;
184	            let after = manifest_version_at(
185	                workspace.runner,
186	                &workspace.root,
187	                release_commit.as_str(),
188	                &path,
189	                manifest.ecosystem(),
190	            )?;
191	            let changed_version = before != after;
192	            if selected.contains(&id) {
193	                if !changed_version || !changed_paths.contains(path.as_ref()) {
194	                    return Err(GraphError::ReleaseIntentStale);
195	                }
196	                observed.insert(id.clone());
197	                entries.push(ReleaseDecisionEntry {
198	                    package: id,
199	                    target_version: after,
200	                    reasons: vec![ReleaseInclusionReason::Changeset],
201	                });
202	            } else if changed_version {
203	                // A changed version without a consumed changeset is an
204	                // unreviewed extra release.  Group/cascade expansion must be
205	                // encoded by the release-PR generator before this boundary is
206	                // widened; failing closed prevents a silent broader publish.
207	                return Err(GraphError::ReleaseIntentStale);
208	            }
209	        }
210	    }
211	    if observed != selected {
212	        return Err(GraphError::ReleaseIntentStale);
213	    }
214	    ReleaseDecisionV1::new(entries).map_err(|_error| GraphError::ReleaseIntentStale)
215	}
216	
