            let before = manifest_version_at(workspace.runner, &workspace.root, &parent, &path, manifest.ecosystem())?;
            let after = manifest_version_at(
                workspace.runner,
                &workspace.root,
                release_commit.as_str(),
                &path,
                manifest.ecosystem(),
            )?;
