    );
    let code = result.unwrap();
    assert_eq!(
        format!("{code:?}"),
        format!("{:?}", ExitCode::SUCCESS),
        "version without --strict on empty workspace should exit 0"
    );
}

// ---------------------------------------------------------------------------
