1	//! Artifact-byte and GitHub-attestation verification for durable releases.
2	//!
3	//! A manifest is only a claim. This module verifies the actual on-disk bytes
4	//! and asks GitHub to validate the signing certificate against the policy
5	//! embedded in the immutable release intent before an executor can upload an
6	//! asset. It intentionally owns no upload side effect.
7	
8	use std::{
9	    fs::{self, File},
10	    path::{Component, Path, PathBuf},
11	    time::Duration,
12	};
13	
14	use callisto_model::{ArtifactManifestV1, CommandRunner, ReleaseIntentV1};
15	
16	use crate::GraphError;
17	
18	const ATTESTATION_TIMEOUT: Duration = Duration::from_secs(120);
19	
20	/// A manifest whose exact local bytes and GitHub provenance have been checked.
21	///
22	/// The constructor is private: callers can obtain this capability only with
23	/// [`verify_artifact_manifest`]. It borrows the manifest so an executor cannot
24	/// silently substitute a different manifest after verification.
25	#[derive(Debug)]
26	pub struct VerifiedArtifactManifest<'a> {
27	    manifest: &'a ArtifactManifestV1,
28	}
29	
30	impl<'a> VerifiedArtifactManifest<'a> {
31	    pub fn manifest(&self) -> &'a ArtifactManifestV1 {
32	        self.manifest
33	    }
34	}
35	
36	/// Verifies every manifest entry against the exact artifact directory.
37	///
38	/// The artifact directory and every candidate are canonicalized, and symbolic
39	/// links are rejected, so a manifest asset name cannot escape the supplied
40	/// build-output directory. Each asset is streamed once for a bounded-memory
41	/// SHA-256 and size comparison. `gh attestation verify` then validates the
42	/// repository, workflow path and commit, source commit, and hosted-runner
43	/// policy declared by the immutable artifact slot.
44	pub fn verify_artifact_manifest<'a, R: CommandRunner>(
45	    intent: &ReleaseIntentV1,
46	    manifest: &'a ArtifactManifestV1,
47	    artifact_root: &Path,
48	    runner: &R,
49	) -> Result<VerifiedArtifactManifest<'a>, GraphError> {
50	    manifest
51	        .validate_for_intent(intent)
52	        .map_err(|source| GraphError::ArtifactManifest { source })?;
53	
54	    let root = canonical_artifact_root(artifact_root)?;
55	    for entry in &manifest.entries {
56	        let path = resolve_asset_path(&root, &entry.slot.asset_name)?;
57	        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
58	            path: path.clone(),
59	            message: error.to_string(),
60	        })?;
61	        let (digest, length) =
62	            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
63	                path: path.clone(),
64	                message: error.to_string(),
65	            })?;
66	        if digest != entry.digest || length != entry.byte_length {
67	            return Err(GraphError::ArtifactBytesMismatch { path });
68	        }
69	
70	        verify_github_attestation(&path, entry, manifest, runner)?;
71	    }
72	    Ok(VerifiedArtifactManifest { manifest })
73	}
74	
75	fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
76	    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
77	        path: artifact_root.to_path_buf(),
78	        message: error.to_string(),
79	    })?;
80	    if !metadata.is_dir() {
81	        return Err(GraphError::UnsafeArtifactPath {
82	            path: artifact_root.to_path_buf(),
83	            reason: "artifact root is not a directory",
84	        });
85	    }
86	    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
87	        path: artifact_root.to_path_buf(),
88	        message: error.to_string(),
89	    })
90	}
91	
92	fn resolve_asset_path(root: &Path, asset_name: &str) -> Result<PathBuf, GraphError> {
93	    let relative = Path::new(asset_name);
94	    if relative.components().count() != 1 || !matches!(relative.components().next(), Some(Component::Normal(_))) {
95	        return Err(GraphError::UnsafeArtifactPath {
96	            path: relative.to_path_buf(),
97	            reason: "asset name is not a single relative file name",
98	        });
99	    }
100	    let candidate = root.join(relative);
101	    let metadata = fs::symlink_metadata(&candidate).map_err(|error| GraphError::ArtifactRead {
102	        path: candidate.clone(),
103	        message: error.to_string(),
104	    })?;
105	    if metadata.file_type().is_symlink() {
106	        return Err(GraphError::UnsafeArtifactPath {
107	            path: candidate,
108	            reason: "symbolic links are not accepted as artifacts",
109	        });
110	    }
111	    if !metadata.is_file() {
112	        return Err(GraphError::UnsafeArtifactPath {
113	            path: candidate,
114	            reason: "artifact is not a regular file",
115	        });
116	    }
117	    let canonical = candidate.canonicalize().map_err(|error| GraphError::ArtifactRead {
118	        path: candidate.clone(),
119	        message: error.to_string(),
120	    })?;
121	    if !canonical.starts_with(root) {
122	        return Err(GraphError::UnsafeArtifactPath {
123	            path: canonical,
124	            reason: "artifact resolves outside artifact root",
125	        });
126	    }
127	    Ok(canonical)
128	}
129	
130	fn verify_github_attestation<R: CommandRunner>(
131	    path: &Path,
132	    entry: &callisto_model::ArtifactManifestEntryV1,
133	    manifest: &ArtifactManifestV1,
134	    runner: &R,
135	) -> Result<(), GraphError> {
136	    let policy = &entry.slot.attestation_policy;
137	    let workflow = format!("{}/{}", policy.repository, policy.workflow_path);
138	    let path_argument = path.to_string_lossy();
139	    let source_commit = manifest.source_commit.as_str();
140	    let args = [
141	        "attestation",
142	        "verify",
143	        path_argument.as_ref(),
144	        "--repo",
145	        policy.repository.as_str(),
146	        "--signer-workflow",
147	        workflow.as_str(),
148	        "--signer-digest",
149	        policy.workflow_commit.as_str(),
150	        "--source-digest",
151	        source_commit,
152	        "--deny-self-hosted-runners",
153	    ];
154	    let output = runner
155	        .run_with_timeout(
156	            "gh",
157	            &args,
158	            path.parent().unwrap_or_else(|| Path::new(".")),
159	            ATTESTATION_TIMEOUT,
160	        )
161	        .map_err(|error| GraphError::ArtifactAttestation {
162	            path: path.to_path_buf(),
163	            message: error.to_string(),
164	        })?;
165	    if output.success() {
166	        Ok(())
167	    } else {
168	        Err(GraphError::ArtifactAttestation {
169	            path: path.to_path_buf(),
170	            message: "GitHub attestation verification failed".to_owned(),
171	        })
172	    }
173	}
