1	#![cfg(unix)]
2	
3	//! Black-box durable-release acceptance tests.
4	//!
5	//! These tests intentionally drive the compiled `callisto` binary over a
6	//! real Git repository. Registry and forge programs are replaced only at the
7	//! process boundary, allowing the test to assert the observable release
8	//! contract without coupling to graph-private prepared-operation types.
9	
10	use std::{
11	    fs,
12	    path::{Path, PathBuf},
13	    process::{Command, Output},
14	};
15	
16	use tempfile::TempDir;
17	
18	fn git(root: &Path, args: &[&str]) -> String {
19	    let output = Command::new("git").args(args).current_dir(root).output().unwrap();
20	    assert!(
21	        output.status.success(),
22	        "git {args:?} failed: {}",
23	        String::from_utf8_lossy(&output.stderr)
24	    );
25	    String::from_utf8(output.stdout).unwrap().trim().to_owned()
26	}
27	
28	fn callisto(root: &Path, args: &[&str]) -> Output {
29	    Command::new(env!("CARGO_BIN_EXE_callisto"))
30	        .args(["--format", "json", "--cwd", root.to_str().unwrap()])
31	        .args(args)
32	        .output()
33	        .expect("callisto binary should be invocable")
34	}
35	
36	const DECISION_PATH: &str = ".callisto/release-decision.json";
37	
38	fn system_git() -> PathBuf {
39	    std::env::var_os("PATH")
40	        .into_iter()
41	        .flat_map(|path| std::env::split_paths(&path).collect::<Vec<_>>())
42	        .map(|directory| directory.join("git"))
43	        .find(|candidate| {
44	            candidate.is_file()
45	                && Command::new(candidate)
46	                    .arg("--version")
47	                    .output()
48	                    .is_ok_and(|output| output.status.success())
49	        })
50	        .expect("a real Git executable must be available before installing the fixture PATH")
51	}
52	
53	/// Builds the exact shape a merged release PR must have: its parent contains
54	/// a pending changeset, while its head changes the manifest and changelog and
55	/// removes that changeset.
56	fn release_commit_fixture() -> (TempDir, String) {
57	    let dir = tempfile::tempdir().unwrap();
58	    let root = dir.path();
59	    git(root, &["init", "-b", "main"]);
60	    git(root, &["config", "user.name", "Callisto Test"]);
61	    git(root, &["config", "user.email", "test@example.invalid"]);
62	    git(root, &["config", "commit.gpgsign", "false"]);
63	    git(root, &["config", "tag.gpgsign", "false"]);
64	    git(
65	        root,
66	        &["remote", "add", "origin", "https://github.com/example/core-crate.git"],
67	    );
68	
69	    fs::write(
70	        root.join("Cargo.toml"),
71	        "[workspace]\nmembers = [\"crates/core\"]\nresolver = \"2\"\n",
72	    )
73	    .unwrap();
74	    fs::create_dir_all(root.join("crates/core/src")).unwrap();
75	    fs::write(
76	        root.join("crates/core/Cargo.toml"),
77	        "[package]\nname = \"core-crate\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
78	    )
79	    .unwrap();
80	    fs::write(root.join("crates/core/src/lib.rs"), "pub fn core() {}\n").unwrap();
81	    git(root, &["add", "."]);
82	    git(root, &["commit", "-m", "initial workspace"]);
83	
84	    let init = callisto(root, &["init", "--yes"]);
85	    assert!(
86	        init.status.success(),
87	        "init failed: {}",
88	        String::from_utf8_lossy(&init.stderr)
89	    );
90	    let config_path = root.join("callisto.toml");
91	    let config = fs::read_to_string(&config_path).unwrap();
92	    fs::write(
93	        config_path,
94	        format!(
95	            "{config}\n[[package]]\nmatch = \"cargo/core-crate\"\npublish-to = [\"crates-io\", \"github-release\"]\n"
96	        ),
97	    )
98	    .unwrap();
99	    git(root, &["add", "."]);
100	    git(root, &["commit", "-m", "configure callisto"]);
101	
102	    let add = callisto(
103	        root,
104	        &[
105	            "add",
106	            "--package",
107	            "core-crate:minor",
108	            "--summary",
109	            "Ship durable release execution",
110	        ],
111	    );
112	    assert!(
113	        add.status.success(),
114	        "add failed: {}",
115	        String::from_utf8_lossy(&add.stderr)
116	    );
117	    git(root, &["add", "."]);
118	    git(root, &["commit", "-m", "add release changeset"]);
119	
120	    let version = callisto(root, &["version", "--emit-decision", DECISION_PATH]);
121	    assert!(
122	        version.status.success(),
123	        "version failed: {}",
124	        String::from_utf8_lossy(&version.stderr)
125	    );
126	
127	    // `version` writes the reviewed manifest and changelog edits.  The release
