40	fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
41	    if global.dry_run {
42	        return Err(CliError::Other(
43	            "release plan needs an output file; remove --dry-run because planning is already read-only".to_string(),
44	        ));
45	    }
46	    let runner = CliCommandRunner;
47	    let workspace = load_workspace(global, &runner)?;
48	    let decision = match args.from_release_commit.as_deref() {
49	        Some(raw) => {
50	            let commit = callisto_model::CommitSha::parse(raw)
51	                .map_err(|error| CliError::Other(format!("invalid merged release commit `{raw}`: {error}")))?;
52	            derive_release_commit_decision(&workspace, &commit)?
53	        }
54	        None => {
55	            let selections = args
56	                .packages
57	                .iter()
58	                .map(|raw| {
59	                    ReleasePackageId::parse(raw).map_err(|error| {
60	                        CliError::Other(format!(
61	                            "invalid release package `{raw}`: {error}; use an exact ecosystem-qualified identity such as cargo/callisto-cli"
62	                        ))
63	                    })
64	                })
65	                .collect::<Result<Vec<_>, _>>()?;
66	            let inference = select_inference();
67	            let version_plan =
68	                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
69	            derive_selected_release_decision(&workspace, &version_plan, &selections)?
70	        }
71	    };
72	    let locator = IgnoreWalkLocator::new(&workspace.root);
73	    let intent = build_release_intent(
74	        &workspace.root,
75	        &locator,
76	        &runner,
77	        &decision,
78	        ExecutionTrustProfileV1::GitCommit,
79	    )?;
80	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
81	        .expect("release plan rejects --dry-run before creating its explicit output");
82	    write_intent(&args.out, &intent, &permit)?;
83	    match global.format {
84	        OutputFormat::Json => write_json(&mut std::io::stdout(), &intent)?,
85	        OutputFormat::Text => println!("Wrote release intent {} to {}", intent.digest(), args.out.display()),
86	    }
87	    Ok(ExitCode::SUCCESS)
88	}
