90	fn inspect(args: ReleaseInspectArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
91	    let value = read_json_file(&args.input)?;
92	    match global.format {
93	        OutputFormat::Json => write_json(&mut std::io::stdout(), &value)?,
94	        OutputFormat::Text => println!(
95	            "{}",
96	            serde_json::to_string_pretty(&value).expect("JSON value serializes")
97	        ),
98	    }
99	    Ok(ExitCode::SUCCESS)
100	}
101	
102	fn reconcile(args: ReleaseReconcileArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
103	    let intent = read_intent(&args.intent)?;
104	    let state = match args.state {
105	        Some(path) => ReleaseStateStore::new(path).load(&intent)?,
106	        None => None,
107	    }
108	    .unwrap_or_else(|| ReleaseExecutionStateV1::pending(&intent));
109	    let report = reconcile_release_execution(&intent, &state)?;
110	    match global.format {
111	        OutputFormat::Json => write_json(&mut std::io::stdout(), report.eligible())?,
112	        OutputFormat::Text => {
113	            for operation in report.eligible() {
114	                println!("eligible: {operation:?}");
115	            }
116	        }
117	    }
118	    Ok(ExitCode::SUCCESS)
119	}
120	
121	fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
122	    let intent = read_intent(&args.intent)?;
123	    let manifest = args
124	        .artifact_manifest
125	        .as_deref()
126	        .map(read_artifact_manifest)
127	        .transpose()?;
128	    match (
129	        intent.artifact_slots.is_empty(),
130	        manifest.as_ref(),
131	        args.artifact_dir.as_deref(),
132	    ) {
133	        (true, None, None) => {}
134	        (true, _, _) => {
135	            return Err(CliError::Other(
136	                "release intent declares no binary artifact slots; omit --artifact-manifest and --artifact-dir"
137	                    .to_owned(),
138	            ));
139	        }
140	        (false, Some(manifest), Some(directory)) => {
141	            let runner = CliCommandRunner;
142	            verify_artifact_manifest(&intent, manifest, directory, &runner)?;
143	        }
144	        (false, _, _) => {
145	            return Err(CliError::Other(
146	                "release intent declares binary artifact slots; provide both --artifact-manifest and --artifact-dir"
147	                    .to_owned(),
148	            ));
149	        }
150	    }
151	    let runner = CliCommandRunner;
152	    let root = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
153	        source,
154	        path: Some(global.cwd.clone()),
155	    })?;
156	    let locator = IgnoreWalkLocator::new(&root);
157	    let explicit_state_directory = args.state.as_deref().and_then(std::path::Path::parent);
158	    let capability =
159	        validate_release_intent_with_state_directory(&root, &locator, &runner, explicit_state_directory, intent)?;
160	    let store = match args.state {
161	        Some(path) => ReleaseStateStore::new(path),
162	        None => ReleaseStateStore::default_for(&root, capability.intent())?,
163	    };
164	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or_else(|| {
165	        CliError::Other(
166	            "release execute cannot run with --dry-run; use release reconcile for a read-only readiness check"
167	                .to_string(),
168	        )
169	    })?;
170	    let mut adapter = PreparedReleaseEffectAdapter;
171	    let state = execute_release_with_artifacts(&capability, &store, &permit, manifest.as_ref(), &mut adapter)?;
172	    match global.format {
173	        OutputFormat::Json => write_json(&mut std::io::stdout(), &state)?,
174	        OutputFormat::Text => println!("Release execution state saved to {}", store.path().display()),
175	    }
176	    Ok(ExitCode::SUCCESS)
177	}
