412	fn bump_target<D: DependencyResolver>(
413	    id: &PackageId,
414	    sev: Severity,
415	    input: &CascadeInput<'_, D>,
416	) -> Result<Version, GraphError> {
417	    let base = input.base.get(id).cloned().ok_or_else(|| {
418	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
419	            path: PathBuf::from(id.name()),
420	            field: "version",
421	        })
422	    })?;
423	    let versioning: &dyn callisto_format::Versioning = match base.grammar() {
424	        callisto_model::VersionGrammar::Pep440 => &callisto_format::Pep440Versioning,
425	        _ => &callisto_format::SemVerVersioning,
426	    };
427	
428	    if let Some(pre) = input.pre {
429	        if pre.mode == callisto_format::PreMode::Pre {
430	            let pinned_base = pre.initial_versions.get(id.name()).unwrap_or(&base);
431	            versioning
432	                .bump_prerelease(pinned_base, sev, &pre.tag, &base)
433	                .map_err(GraphError::Bump)
434	        } else {
435	            // PreMode::Exit: finalize the current pre-release to a stable version.
436	            // Bumping the on-disk pre-release version (e.g. "1.0.0-alpha.2") with
437	            // any severity that matches the pre-release target strips the tag and
438	            // produces the stable version (e.g. "1.0.0").
