18	pub fn pre_mutation_checks<D: DependencyResolver>(
19	    _graph: &D,
20	    groups: &GroupTable,
21	    base: &BTreeMap<PackageId, Version>,
22	    tags: &TagIndex,
23	    napi: &NapiTargetsIndex,
24	    root: &Path,
25	) -> Result<GroupCheckOutcome, GraphError> {
26	    let mut outcome = GroupCheckOutcome::default();
27	
28	    for g in groups.fixed.values() {
29	        let released: Vec<PackageId> = g
30	            .members(GroupMemberKind::Package)
31	            .filter_map(|m| match m {
32	                GroupMember::Package(ref id) => {
33	                    if tags.last_tag(id).is_some() {
34	                        Some(id.clone())
35	                    } else {
36	                        None
37	                    }
38	                }
39	                _ => None,
40	            })
41	            .collect();
42	
43	        let fresh: Vec<PackageId> = g
44	            .members(GroupMemberKind::Package)
45	            .filter_map(|m| match m {
46	                GroupMember::Package(ref id) => {
47	                    if tags.last_tag(id).is_none() {
48	                        Some(id.clone())
49	                    } else {
50	                        None
51	                    }
52	                }
53	                _ => None,
54	            })
55	            .collect();
56	
57	        let pairs: Vec<(PackageId, Version)> = released
58	            .iter()
59	            .filter_map(|id| base.get(id).map(|v| (id.clone(), v.clone())))
60	            .collect();
61	
62	        if pairs.len() > 1 {
63	            let first_v = &pairs[0].1;
64	            let mut divergent = false;
65	            for (_id, v) in &pairs[1..] {
66	                if v.grammar() != first_v.grammar() {
67	                    return Err(GraphError::GroupGrammarMismatch {
68	                        group: g.name.clone(),
69	                        members: pairs,
70	                    });
71	                }
72	                if Version::compare(v, first_v).ok() != Some(std::cmp::Ordering::Equal) {
73	                    divergent = true;
74	                }
75	            }
76	            if divergent {
77	                return Err(GraphError::FixedGroupDivergent {
78	                    group: g.name.clone(),
79	                    members: pairs,
80	                });
81	            }
82	        }
83	
84	        if !fresh.is_empty() {
85	            outcome.new_members.insert(g.name.clone(), fresh);
86	        }
87	
88	        // napi.targets drift cross-check (§G.8.4).
89	        if let Some(declared) = napi.declared_for(&g.name) {
90	            outcome.diagnostics.extend(napi_drift(g, declared, root));
91	        }
92	    }
93	
94	    Ok(outcome)
95	}
